CREATE DATABASE IF NOT EXISTS `knowpolitics` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `knowpolitics`;

DROP TABLE IF EXISTS `mlas`;
CREATE TABLE `mlas` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `state` VARCHAR(50) NOT NULL,
  `constituency_no` INT NOT NULL,
  `constituency` VARCHAR(150) NOT NULL,
  `name` VARCHAR(150) NOT NULL,
  `party` VARCHAR(100) DEFAULT NULL,
  `contact` VARCHAR(50) DEFAULT NULL,
  `image` VARCHAR(255) DEFAULT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX `idx_state` (`state`),
  INDEX `idx_constituency_no` (`constituency_no`),
  INDEX `idx_party` (`party`),
  INDEX `idx_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

